insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Personal Hygiene and Food Hygiene', 'B7.1.1.1', 'Demonstrate knowledge of basic concept of staying healthy', 'B7.1.1.1.1', 'Discuss the need to stay healthy', '1. Explain what is meant by staying healthy. E.g. Staying healthy: physical, mental, and social wellbeing, and as a resource for living a full life—exercise the body, have enough rest, eat a balanced diet, avoid drug abuse and negative peer pressure; 2. Discuss and present in groups the consequences of not taking good care of one’s body E.g., Contract disease and fall ill. NB: Use different ways or means for presentation—power point, posters, pictures, illustrations (differentiation).; 3. Research and write on materials and strategies (ways) used for improving personal hygiene and discuss, in groups.', 10),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Personal Hygiene and Food Hygiene', 'B7.1.1.1', 'Demonstrate knowledge of basic concept of staying healthy', 'B7.1.1.1.2', 'Describe ways of maintaining personal hygiene', '1. In groups, discuss ways of maintaining personal hygiene. E.g., - Wash the body often. - Clean the teeth at least twice a day. - Wash hands after visiting the toilet.; 2. Demonstrate the following in groups. E.g., Care of finger nails, hair, nose, ear, mouth and teeth', 20),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Personal Hygiene and Food Hygiene', 'B7.1.1.1', 'Demonstrate knowledge of basic concept of staying healthy', 'B7.1.1.1.3', 'Discuss food hygiene', '1. Explain what is meant by food hygiene. E.g., Conditions and measures needed to ensure safety of food from production to consumption.; 2. Research into food hygiene practices, in groups and report in class for discussion. E.g., Proper storage and preservation of food.', 30),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Personal, Workshop and Food Laboratory Safety', 'B7.1.2.1', 'Demonstrate knowledge of preventing accidents in the workshop/site and laboratory', 'B7.1.2.1.1', 'Describe accidents in the workshop/site/laboratory', '1. Explain what is meant by accidents. E.g., Accidents in the workshops are injuries that occur in the workshop/site or laboratory unexpectedly.; 2. Discuss the types of accidents that occur in the workshop. E.g., Falls, cuts, bruises and explosions.; 3. Predict the causes of accidents that can occur in the workshop/food laboratory. E.g., Tiredness/fatigue, poor lightening and ventilation.', 40),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Personal, Workshop and Food Laboratory Safety', 'B7.1.2.1', 'Demonstrate knowledge of preventing accidents in the workshop/site and laboratory', 'B7.1.2.1.2', 'Explain the need for keeping the workshop/site and the laboratory safe', '1. Identify personal safety measures in the workshop/site/food laboratory. E.g., Proper use of personal protective equipment in the workshop and laboratory and adherence to safety rules and regulations.; 2. Discuss how to keep tools and equipment safe to prevent accidents in the workshop /site/food/sewing laboratory. E.g., Proper storage of food, materials, tools and equipment.; 3. Demonstrate ways of preventing accidents in the workshop/site//food laboratory. E.g.; Follow instructions and do not rush through work; Good lighting and ventilation, work systematically and carefully; Keep oneself from harm, observe safety precautions,; Wear personal protective equipment (PPE) such as goggles, nose masks and boots.', 50),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Environmental Health', 'B7.1.3.1', 'Demonstrate knowledge of basic concept of Environmental Health', 'B7.1.3.1.1', 'Discuss the factors of environmental health', '1. Explain what is meant by Environmental Health. E.g., It is a way of protecting quality of life through the prevention and treatment of disease that relates to the natural and built environment that may affect human health and fosters healthy and safe communities.; 2. Identify the factors (constituents/pillars) of environmental health, in groups E.g., Disease control, clean water, sanitation and hygiene.; 3. Identify and discuss the causes of environmental health and other sources and report in class. E.g., Air, water and soil pollutions, chemical exposures; 4. Research the consequences of poor environmental health, in groups and present for class discussions. E.g., Transmission of diseases such as cholera, diarrhoea, dysentery, hepatitis A, typhoid, polio, Novel Coronavirus (COVID-19) and exacerbates stunting', 60),
('Basic 7', 'Career Technology', 'career technology', 'Personal Hygiene and Food Hygiene', 'Environmental Health', 'B7.1.3.1', 'Demonstrate knowledge of basic concept of Environmental Health', 'B7.1.3.1.2', 'Demonstrate the preventive measures of environmental health', '1. Identify preventive measures of poor environmental health. E.g. - Avoid polluting water bodies - Avoid littering - Avoid defecating indiscriminately; 2. Present findings in groups.; 3. Undertake a project in tree planting around the school/community.; 4. Document the growth stages of the tree and report in class for appraisal using charts, pictures and videos.', 70),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Compliant Materials', 'B7.2.1.1', 'Demonstrate knowledge of basic concept of compliant materials', 'B7.2.1.1.1', 'Describe compliant materials', '1. Explain what is meant by compliant materials E.g., Compliant materials are materials that have recognised, predictable and consistent properties such as paper/card, fabric/textiles.; 2. Sort out compliant materials from the variety of available materials.; 3. Write a summary of the explanation and sorting.', 80),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Compliant Materials', 'B7.2.1.1', 'Demonstrate knowledge of basic concept of compliant materials', 'B7.2.1.1.2', 'Distinguish between types of compliant materials', '1. Classify the various compliant materials under their types: - Paper - Card - Fabric/Textile; 2. Give examples of each class of compliant materials: - Paper—copy paper, construction paper - Card—solid white board, corrugated card, - Fabric/Textile—cotton, nylon; 3. Read out the summary of the lesson.; 4. Create a photo album and display for appraisal.', 90),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Compliant Materials', 'B7.2.1.1', 'Demonstrate knowledge of basic concept of compliant materials', 'B7.2.1.1.3', 'Explain how compliant materials are manufactured/produced', '1. Search for information on how paper/card is obtained, in groups. E.g., Paper is made from wood; a tree is felled, broken into chips, chips are boiled in water and chemicals added to form pulp; the pulp is pressed with rollers. The more the layers, the thicker the paper i.e. card.; 2. Find information from books and other sources on how fabric/textile is obtained, in groups E.g., Fabric/Textile is obtained from natural and man-made fibres which are turned into yarns and threads. They are made through weaving, knitting, crocheting, braiding or bonding, knotting, and felting.; 3. Write out findings and present in class.', 100),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Resistant Materials', 'B7.2.2.1', 'Demonstrate knowledge of basic concept of resistant materials', 'B7.2.2.1.1', 'Describe resistant materials', '1. Explain what is meant by resistant materials. E.g., Resistant materials are materials that are not pliable or flexible and cannot be easily compressed with bare hands (plastic, wood, metal, ceramics, glass).; 2. Sort out resistant materials from the variety of available materials E.g., plastic, wood, metal, ceramics, glass and their composites,; 3. Write down the summary of the explanation and sorting.', 110),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Resistant Materials', 'B7.2.2.1', 'Demonstrate knowledge of basic concept of resistant materials', 'B7.2.2.1.2', 'Distinguish between the types of resistant materials', '1. Sort out different resistant materials into various categories E.g., - Plastics—thermosetting plastics and thermoplastics - Wood—hardwoods, softwoods and manufactured (man-made) boards - Metals—ferrous, non-ferrous, alloys and smart.; 2. Identify and write the names of the various types of resistant materials under their categories and present in class for discussion.', 120),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Resistant Materials', 'B7.2.2.1', 'Demonstrate knowledge of basic concept of resistant materials', 'B7.2.2.1.3', 'Explain how each of the resistant materials is manufactured/produced', '1. Discuss the two main sources (natural and synthetic) from which plastics are obtained. E.g. - Natural resources: plants (cellulose), trees, animals, insects - By-products: table tennis balls, acetate films, wrapping; rubber, roads, paint, decoration, glues, polish - Synthetic sources: crude oil, coal and natural gas - By-products: chemically produced plastics—polymerising vinyl chloride (PVC), polystyrene, polyethylene, acrylic.; 2. Find out information from different sources including online, on the two types of plastics and give examples. E.g. - Thermoplastics: polythene, PVC, nylon - Thermosetting plastics: urea formaldehyde, polyester resin, epoxy resin; 3. Make a table and match products to the types of plastics they are made from, E.g. Material Products Polythene toys, carrier bags, packaging film Urea formaldehyde textile, (white) electrical fittings, adhesives (wood)', 130),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Smart and Modern Materials', 'B7.2.3.1', 'Demonstrate understanding of the properties of smart and modern materials', 'B7.2.3.1.1', 'Explore the general properties of smart and modern materials', '1. Describe smart and modern materials. E.g. - Smart materials (intelligent or responsive materials) are designed materials that have one or more properties that can be significantly changed in a controlled fashion by external stimuli, such as stress, moisture, electric or magnetic fields, light, temperature, pH or chemical compounds. - Modern materials are materials developed through the invention of new or improved process to have improved properties and are used for sportswear, medical and safety wear, and fashion clothing.; 2. Identify the main factors that affect the properties of smart and modern materials. E.g. Light, temperature (hot/cold/warm), moisture.; 3. Describe the effects of light on smart and modern materials and products. E.g. - Light causes photomechanical materials to change shape when exposed to it. - Photochromic materials change colour in response to light; 4. Explain the effects of temperature on smart and modern materials and products. E.g., Thermochromic materials change in colour depending on temperature', 140),
('Basic 7', 'Career Technology', 'career technology', 'Materials for Production', 'Food Commodities (animal and Plant Sources)', 'B7.2.4.1', 'Demonstrate knowledge of basic food commodities', 'B7.2.4.1.1', 'Discuss food commodities', '1. Explain what is meant by food. E.g., Food is any edible substance either solid or liquid which when eaten is used by the body to maintain life.; 2. Explain what is meant by food commodities. E.g., Food commodities generally refer to ingredients needed to produce different varieties of food.; 3. Give examples of common food commodities in the community E.g., fish, cassava, okro, orange, milk, meat; 4. Enumerate the two (2) main sources of food commodities. E.g. Plant and animal 5.Classify food commodities under the two main sources, i.e., plant source and animal source Plant Animal cassava, okro, orange fish, milk, meat 6.Discuss reasons for eating food; E.g., To satisfy our hunger, build body, provide heat energy, protect body from diseases.; 7. Make a chart on the two (2) main sources of food commodities and their examples.', 150),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Measuring and Marking Out', 'B7.3.1.1', 'Demonstrate understanding of measuring and marking out tools and equipment for production', 'B7.3.1.1.1', 'Classify and use measuring and marking out tools and equipment for production', '1. Identify and classify the types of measuring and marking out tools and equipment. Example: Place of work Measuring Marking out Tools Tools Food laboratory (kitchen) measuring cups grater and cutter Sewing workshop/ tape measure, pencil, tailor’s chalk laboratory yard/ meter rule Building site surveyor’s tape profile board, peg, chalk Wood workshop tape measure, pencil, marking gauge, folding rule marking knife Metal/plastic workshop steel rule pair of compasses, scriber, pair of dividers; 2. Think-write-pair and share at plenary session, the uses of each tool and equipment found in: - Food laboratory (kitchen) - Sewing workshop/laboratory - Building site - Wood workshop - Metal/plastic workshop; Measuring Tools; measuring cups; tape measure, yard/ meter rule; surveyor’s tape; tape measure, folding rule; steel rule; 3. Discuss the importance of measuring and marking out tools. E.g., Accuracy, avoidance of waste of material, achieving desired results 4. Identify from displayed realia or pictures, tools and equipment used for measuring and marking out: - Food laboratory (kitchen for liquids/dry ingredients: weighing scale, measuring cups, spoons, calabash, olonka - Sewing workshop/laboratory: tape measure, yard rule - Building site: tape measure, builder’s square, head pan, straight edge - Wood workshop: tape measure, folding rule, try-square, marking knife - Metal workshop: tape measure, steel rule, pair of compasses 5. Sketch and label parts of measuring and marking out tools and display sketches for appraisal. 6. Demonstrate how to use the measuring and marking out tools and equipment.', 160),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Measuring and Marking Out', 'B7.3.1.1', 'Demonstrate understanding of measuring and marking out tools and equipment for production', 'B7.3.1.1.2', 'Demonstrate how to care for and maintain measuring and marking out tools and equipment used for production', '1. Share experiences from home on how to care for tools and equipment used for production.; 2. Discuss cleaning agents/materials used to clean and maintain tools and equipment based on the respective material used in making the tool. E.g. Silvo for cleaning silver, Brasso for cleaning brass, oil to avoid rust, cloth for cleaning and dusting.; 3. Demonstrate how to care for measuring and marking out tools and equipment according to the material used in making them.', 170),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Cutting/shaping', 'B7.3.2.1', 'Demonstrate understanding of cutting/shaping tools and equipment for production', 'B7.3.2.1.1', 'Identify cutting and shaping tools and equipment used for production', '1. Identify the displayed cutting tools: - Food laboratory:; Cutting tools: All kinds of kitchen knives (pairing, chopping bread), biscuit cutters.; Shaping tools: Cake tins, moulds, scoops for ice cream etc. - Sewing workshop/laboratory - . Scissors, pinking shears, seam ripper and French curves) - Woodwork—Rip saws, cross cut saw, tenon saw, firmer chisel, mortice chisel, spoke shave, rasp file. - Building—Bolster, brick hammer, mould box - Metal/plastics—Hacksaw, junior hacksaw, hand file, flat file, square file, rectangular file, file card, cold chisels, drills and bits', 180),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Cutting/shaping', 'B7.3.2.1', 'Demonstrate understanding of cutting/shaping tools and equipment for production', 'B7.3.2.1.2', 'Use appropriate skills in cutting, chopping, slicing, dicing and shaping products', '1. Demonstrate the appropriate techniques in cutting, chopping, slicing and dicing in food production.; 2. Demonstrate the appropriate techniques in cutting, paring, moulding in wood, metal and building.', 190),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Cutting/shaping', 'B7.3.2.1', 'Demonstrate understanding of cutting/shaping tools and equipment for production', 'B7.3.2.1.3', 'Demonstrate how to care for and maintain cutting and shaping tools used for production', '1. Share experiences on how to care for, and maintain cutting and shaping tools and equipment for production. E.g., oil metal parts of tools, wash and clean mould box.; 2. Identify cleaning agents used to clean tools and equipment according to the material used in cleaning cutting and shaping tools E.g., Silvo and grounded and sifted egg shell for cleaning stainless steel, oil for cleaning metal parts of tools.; 3. Demonstrate how to care for and maintain cutting and shaping tools and equipment according to the material used in making them and discuss in class.', 200),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Joining and Assembling', 'B7.3.3.1', 'Demonstrate understanding of joining and assembling materials, tools and equipment used for production', 'B7.3.3.1.1', 'Describe joining and assembling materials, tools and equipment used for making artefacts/products', '1. Identify joining and assembling materials, tools and equipment used for: - Sewing and crocheting—Thread, needle, crocheting hooks/ pins, sewing machine - Food production—Corn starch, gluten, tapioca, gelatin, egg white, milk. - Woodwork—Mallet, glues, clamps, screws - Metal work/Plastic—Soldering bit, bolts and nuts, epoxy resin, rivets, mallet, screws, screw drivers - Building—cement - Paper—glue; 2. Research for more joining and assembling materials, tools and equipment using ICT tools and other sources and discuss in groups.; 3. Sketch/make an album of joining and assembling materials, tools and equipment.; 4. Display the sketches/album for appraisal.', 210),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Joining and Assembling', 'B7.3.3.1', 'Demonstrate understanding of joining and assembling materials, tools and equipment used for production', 'B7.3.3.1.2', 'Use appropriate skills for joining and assembling artefacts using the materials, tools and equipment', '1. Demonstrate the appropriate techniques in using joining and assembling materials and tools in: - Sewing and crocheting—stitching, knotting/looping - Food production— (cooking methods - boiling and stewing) - Wood products—nailing, bolting, screwing, gluing - Metal products/Plastic—soldering, using bolts and nuts, screwing, using adhesives, bolts and nuts - Building —bonding of bricks, blocks and stones. - Paper work—gluing', 220),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B7.3.4.1', 'Demonstrate knowledge and understanding of the Kitchen Essentials', 'B7.3.4.1.1', 'Describe kitchen essentials', '1. Explain what is meant by basic kitchen essentials. E.g., Kitchen essentials are indispensable/vital tools and equipment needed/necessary for meal preparation and service, e.g. saucepan, plate, can opener, colander, cutting board, vegetable peeler, soup tureen, crockery', 230),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Kitchen Essentials', 'B7.3.4.1', 'Demonstrate knowledge and understanding of the Kitchen Essentials', 'B7.3.4.1.2', 'Demonstrate skills in the classification of kitchen essentials', '1. Identify and classify kitchen essentials according to sizes. E.g. - Small: spoons, can opener - Large: refrigerator, cooker, broilers, cupboard - Mechanical: blender, food mixers; 2. Present responses on the classified kitchen essentials for appraisal.', 240),
('Basic 7', 'Career Technology', 'career technology', 'Tools, Equipment and Processes', 'Finishes and Finishing', 'B7.3.5.1', 'Demonstrate knowledge of finishes and finishing', 'B7.3.5.1.1', 'Identify finishes and finishing applied to products/ artefacts', '1. Explain what is meant by finishes and finishing. E.g., Finishes are the substances applied on the surfaces of products/artefacts. Finishing is the final surface treatment given to products/artefacts to improve their beauty, attractiveness and protection.; 2. Identify types of finishes E.g., lacquer, emulsion paint, oil paint, vanish, ceramic tiles, stones, plaster of Paris (POP), 3-D floor, wall paper.; 3. Identify solvents used to thin finishes. E.g., thinner for lacquer polish, turpentine for oil paint, water for emulsion paint. Solvents make mixture flow easily.; 4. Explain what is meant by garnishes. E.g., Garnishes are small, colourful, bits of food that are used to enhance the appearance and texture of dishes. Garnishes provide food with something that adds flavour and decorative colour.; 5. Discuss ways of applying finishing to food products. E.g., Food can be ‘finished’ using garnishes; 6. Choose garnishes of colour and flavours that complement the food to be garnished. E.g., Use carrots, green pepper, lettuce and tomatoes to garnish pale foods.', 250),
('Basic 7', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B7.4.1.1', 'Demonstrate understanding of structures in construction', 'B7.4.1.1.1', 'Outline the uses of structures in construction', '1. Explain what is meant by structures in construction. E.g., Method of supporting loads (triangulation, truss) to prevent collapse.; 2. Identify and classify structures under natural and man-made E.g. - Natural: structures created by nature to provide support (spider web, honeycomb and human skeleton) - Man-made: structures made by man to provide protection and support, (chairs, helmets, suspension bridge); 3. Classify structures under frame and shell. E.g. - Frame structures: crane, electricity pylon and building - Shell structures: body of motor car shaped from panels.; 4. Discuss the uses of structures in construction. E.g. - Carrying loads for which they were designed without toppling over or collapsing - Supporting the various parts of artefacts; 5. Make sketches of both frame and shell structures and prepare a sketch album to use as materials for learning structures.; 6. Display the sketch album for appraisal', 260),
('Basic 7', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B7.4.1.1', 'Demonstrate understanding of structures in construction', 'B7.4.1.1.2', 'Discuss the causes of structural failures in construction', '1. Explain what is meant by structural failure in construction. E.g., when a structure collapses or fails to do its job.; 2. Identify types of structural failure E.g., cracks, splits, breakages in structures; 3. Observe where structural failures occur in structures in the environment. E.g., buildings, bridges, furniture; 4. Discuss causes of structural failures. E.g., poor design, poor material, weak joint and fatigue; 5. Discuss how static and dynamic forces can cause structures to fail. E.g. - Static force—stationary force due to the structure’s own weight or the load being carried - Dynamic forces—moving force produced by wind, sea, vehicles and people.; 6. Make sketches and notes on structural failures, in groups.; 7. Display sketches for appraisal.', 270),
('Basic 7', 'Career Technology', 'career technology', 'Technology', 'Simple Structures and Mechanisms, Electric and Electronic Systems', 'B7.4.1.1', 'Demonstrate understanding of structures in construction', 'B7.4.1.1.3', 'Design and make simple structures', '1. Identify compliant and resistant materials, tools and equipment for making structures. E.g.: paper, cardboards, wood, metal and plastic; 2. Plan and design the artefact. E.g., prepare working drawings showing dimensions; 3. Make mock-ups of simple structures. E.g., frame and shell. Note: Examples of structures are car bodies, types of roofing, chairs, aircraft, train, radio and cupboard.; 4. Test and evaluate the mock-ups by indicating the strengths and weaknesses of the structures and make modifications; 5. Display the mock-ups for appraisal', 280),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B7.5.1.1', 'Demonstrate knowledge and skills of drawing materials, instruments/equipment, lines and their applications, and freehand sketching', 'B7.5.1.1.1', 'Identify drawing materials, instruments and equipment used for Graphic Communication', '1. Identify drawing materials, instruments and equipment. E.g., drawing materials, instruments and equipment (drawing paper, drawing board, tee square, pencils, a pair of compasses, a pair of dividers, rule); 2. Discuss the uses of drawing materials, tools and equipment. E.g. - Drawing paper—drawings are made on it - Drawing board—drawing paper is fixed on it for work to be done; 3. Demonstrate appropriate usage and manipulation of drawing materials, instruments and equipment. E.g. How to manipulate the instruments/equipment-proper handling of compass, T- square, set squares.; 4. Demonstrate how to care for and maintain the drawing materials and instruments/equipment.; 5. Use a clean tissue to wipe the surface of the instruments/equipment Note: Do not drop the instruments/equipment.', 290),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B7.5.1.1', 'Demonstrate knowledge and skills of drawing materials, instruments/equipment, lines and their applications, and freehand sketching', 'B7.5.1.1.2', 'Discuss the types of lines used in graphic communication', '1. Identify lines used in communicating ideas. E.g., horizontal lines, vertical lines, inclined lines, arcs, continuous thick and thin lines, short dashes,; 2. Describe the features and uses of the lines. E.g. - Continuous thick lines—for drawing outlines; - Continuous thin lines—for drawing construction lines; 3. Illustrate the applications of lines in drawn objects. E.g., indicate dimension lines showing the dimension of an object; 4. Make a chart on how the lines are applied in drawing.; 5. Present the chart for appraisal.', 300),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B7.5.1.1', 'Demonstrate knowledge and skills of drawing materials, instruments/equipment, lines and their applications, and freehand sketching', 'B7.5.1.1.3', 'Make sketches of lines, curves, objects, and write the letterings', '1. Identify lower- and upper-case letters. E.g. - Lowercase—a, b, c, d - Upper case—A, B, C, D; 2. Discuss the principles of lettering. E.g. - Titles should be 8mm high - General information is usually about 6mm high Note: Titles and dimensions are usually written in upper case; 3. Set out drawing paper and prepare title block indicating name, school, class, date and drawing number.', 310),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Communicating Designs', 'B7.5.1.1', 'Demonstrate knowledge and skills of drawing materials, instruments/equipment, lines and their applications, and freehand sketching', 'B7.5.1.1.4', 'Make sketches of objects 1.Discuss what is meant by sketching', 'E.g., a quick way of putting ideas down using freehand with a pencil or any other marker.; 2. Illustrate the techniques of sketching objects in two-dimensional (2-D) plane figures. E.g., square, triangle, circle, rectangle, oval; 3. Illustrate the techniques of sketching objects in three dimensional (3-D) E.g., isometric, oblique, perspective; 4. Practise sketching of plane objects and pictorial objects to build an album and display for appraisal.', 320),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B7.5.2.1', 'Demonstrate understanding of Designing', 'B7.5.2.1.1', 'Work with a given design brief', '1. Study a given design brief to identify the problem.; 2. Analyse the problem and list the possible ideas for the solution.; 3. Discuss ideas in groups.', 330),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Designing', 'B7.5.2.1', 'Demonstrate understanding of Designing', 'B7.5.2.1.2', 'Generate ideas', '1. Use freehand sketching to generate three possible ideas for solving the identified problem and write descriptive notes.; 2. Verify if the generated ideas satisfy the solution for the problem identified.; 3. Select the best design and draw it in a pictorial form.; 4. Provide suitable dimensions to the selected design.; 5. Prepare a simple working drawing of the selected design for the working drawing prepared in communication design such as front elevation, plan and end view.', 340),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Food Commodities (animal and Plant Sources)', 'B7.5.3.1', 'Demonstrate skills in planning meals for various members of the family', 'B7.5.3.1.1', 'E.g., nutritional requirements of family members, food in season', '1. Identify and explain the different types of meals served in a day. E.g., breakfast, lunch, snack, elevenses, brunch and supper.; 2. Explain the factors to consider when planning meals. E.g.; Nutritional needs of family members; Food available; Family budget', 350),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Food Commodities (animal and Plant Sources)', 'B7.5.3.1', 'Demonstrate skills in planning meals for various members of the family', 'B7.5.3.1.2', 'Demonstrate skills in planning for preparing food using moist methods of cooking', '1. Discuss reasons for cooking food, in groups. E.g.: - make food edible, - improve flavour of food, kill germs.; 2. Identify the different moist methods of cooking. E.g.: Moist Method—boiling, stewing, poaching', 360),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B7.5.4.1', 'Demonstrate skills of making artefacts/ products', 'B7.5.4.1.1', 'Demonstrate skills in preparing food using moist methods of cooking BOILING & STEWING', '1. Prepare a meal by choosing from any one of the three (3) types of boiling methods of cooking with an accompaniment stew, in groups. 2. Present /display meals for appraisal. Note: Guide learners to appreciate, appraise and critique their works and use the feedback to make modifications or undertake new practical.', 370),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B7.5.4.1', 'Demonstrate skills of making artefacts/ products', 'B7.5.4.1.2', 'Demonstrate skills of making artefacts/products in sewing and crocheting SEWING', '1. Make specimens or samples of basic sewing stitches individually. E.g., tacking (even, long and short), running stitches, back stitches, overcasting.; 2. Display specimens for appraisal. CROCHETING; 1. Make specimens of basic crocheting stitches. E.g., chain, slip stitches, double crochet, treble.; 2. Display specimens for appraisal.', 380),
('Basic 7', 'Career Technology', 'career technology', 'Designing and Making of Artefacts/products', 'Making Artefacts from Compliant, Resistant Materials and Food Ingredients', 'B7.5.4.1', 'Demonstrate skills of making artefacts/ products', 'B7.5.4.1.3', 'Make mock-ups using compliant materials', '1. Organise the card board or paper as the main materials in place for the work.; 2. Use the cutting list together with the working drawings to undertake the measuring, marking out and cutting of the various parts of the design using appropriate tools and equipment.; 3. Check the various parts and dimensions to ensure an accurate surface development of the artefact.; 4. Fold the parts of the surface developed to obtain the required artefact.; 5. Use appropriate joining materials, tools/equipment to complete the required artefact.; 6. Apply a suitable finish on the artefact; 7. Test and evaluate artefact for modifications.', 390),
('Basic 7', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B7.6.2.1', 'Demonstrate understanding of Establishing and managing a Small business Enterprise', 'B7.6.2.1.1', 'Explain what is meant by ‘entrepreneurship’ and ‘entrepreneur’', 'E.g.; 1. Entrepreneurship is the activity of setting up a business or businesses, taking on financial risks in the hope of profit.; 2. An entrepreneur is a person who sets up a business or businesses taking on financial risks in the hope of making profit.', 400),
('Basic 7', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B7.6.2.1', 'Demonstrate understanding of Establishing and managing a Small business Enterprise', 'B7.6.2.1.2', 'Describe the characteristics of a successful entrepreneur', '1. Explain the characteristics of an entrepreneur. E.g. An entrepreneur is a person who sets up a business or businesses taking on financial risks in the hope of making profit. E.g. Characteristics of an entrepreneur: creative, passionate, motivated, optimistic, future oriented, persuasive, flexible, resourceful 2.Discuss the characteristics that lead to successful entrepreneurship Note: Use illustrations, ICT tools and other sources to facilitate discussions. E.g., Opportunity seeking, goal setting, risk taking, perseverance and persistence, self- confidence, commitment to work, hardworking, planning, information seeking, and problem-solving skills.', 410),
('Basic 7', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B7.6.2.1', 'Demonstrate understanding of Establishing and managing a Small business Enterprise', 'B7.6.2.1.3', 'Explain the advantages and disadvantages of being an entrepreneur', '1. Discuss in groups, the advantages and disadvantages of being an entrepreneur E.g. - Advantage: self-management, employment creation - Disadvantage: irregular income stream, difficulty in securing funds', 420),
('Basic 7', 'Career Technology', 'career technology', 'Entrepreneurial Skills', 'Establishing and Managing a Small Business Enterprise', 'B7.6.2.1', 'Demonstrate understanding of Establishing and managing a Small business Enterprise', 'B7.6.2.1.4', 'Identify entrepreneurial opportunities in the locality', '1. Explore your locality, observe, and interact with entrepreneurs, taking into consideration the safety and welfare of learners.; 2. Research for entrepreneurial opportunities E.g., mechanical engineering, welding, fitting, hairdressing, car washing, catering, masonry, block work, wood work, tiling, fashion designing, farming (fish and agriculture)) in the locality.; 3. Write down the names of some popular enterprises seen in your locality.; 4. Visit a few enterprises in your potential trade area and find out the following: - How the business was started - The challenges the business is facing - Solutions to the challenges; 5. Write down the findings for presentation in class', 430),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B7.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements and principles of design and as a medium for creative expression of design in nature and the manmade environment', 'B7.1.1.1.1', 'Demonstrate understanding of design as a concept and its importance and role as a medium for creative expression of design in nature and the manmade environment', 'Exemplar; 1. Research to determine and record the meaning, importance and role of design in nature and the manmade environment for reflection and discussion.; 2. Identify and reflect on selected natural and manmade designs to appreciate and determine how design in nature has influenced manmade designs to benefit society for appreciation and discussion. Design inspired by Beak of kingfisher bird inspired the palm Colourful bird Shinkansen Bullet Train – Japan Source: Pinterest.com; 3. Compare and contrast selected natural and manmade designs to determine and record their similarities and differences for reflection and inspiration to create and illustrate own design ideas (e.g. rivers/roads, anthills/houses, etc.) Source: Pinterest.com Anthill inspired Eastgate Building in Harare', 10),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B7.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements and principles of design and as a medium for creative expression of design in nature and the manmade environment', 'B7.1.1.1.2', 'Research to identify and record what constitutes the ‘elements of design’ in nature and as building blocks for creative expression of design ideas', 'Exemplar; 1. Research to deduce and record what constitutes the ‘elements of design’ and their application as building blocks for creative expression of design for reflection and discussion. Examples: dots, lines, shapes Source: Pinterest.co m', 20),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Design in Nature and Manmade Environment', 'B7.1.1.1', 'Demonstrate understanding of design as a concept in relation to the elements and principles of design and as a medium for creative expression of design in nature and the manmade environment', 'B7.1.1.1.3', 'Research to identify and record in writing what constitutes the principles of design and describe how they are used to organise the elements of design into building blocks for creative expression of design in nature and the manmade environment', 'Exemplar; 1. Search for and organise relevant information to describe and record the principles of design and how they apply in nature and the manmade environment for reflection. Examples: balance, rhythm, repetition Manmade design Natural designs Zimbabwe Source: Pinterest.com; 2. Identify, describe and record examples of principles of design in nature and the manmade environment for appreciation and discussion.; 3. Apply knowledge gained to select examples of elements and principles of design to create own designs using available manual and digital tools, materials and techniques for appreciation, display and feedback. Source: Google.com', 30),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B7.1.2.1', 'Design Demonstrate understanding and use of (outline drawing, shading, colouring) and modelling media and techniques for creative expression of design ideas', 'B7.1.2.1.1', 'Explore available manual and digital tools, materials and techniques for outline drawing, shading and colouring to create designs from lines and simple shapes', 'Exemplar; 1. Explore to determine and document the nature and suitability of available manual tools, materials and techniques for outline drawing, shading, and colouring for appreciation and reflection. E.g. of tools: T-square, set square, protractor/paper/cardboard/pencil. Tools d', 40),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B7.1.2.1', 'Design Demonstrate understanding and use of (outline drawing, shading, colouring) and modelling media and techniques for creative expression of design ideas', 'B7.1.2.1.2', 'Demonstrate skills in using available digital tools, materials and techniques for freehand and outline drawing, shading and colouring to create designs from lines, simple shapes and forms', 'Exemplar; 1. Explore available digital tools, materials and techniques to determine and document their suitability for drawing, shading and colouring for appreciation and reflection. Di; 2. Identify, select and experiment the use of available digital tools, materials and techniques for freehand and outline drawing, shading and colouring to create designs from lines, simple shapes and forms for sharing and appraising. Refer to: YouTube videos: Start drawing Part 2-6: Drawing Shapes; Understanding Eye Level; etc.; 3. Exhibit own portfolio of freehand and outline drawings and colour work to share design ideas for appreciation, appraising and feedback.', 50),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Drawing, Shading, Colouring and Modelling for Design', 'B7.1.2.1', 'Design Demonstrate understanding and use of (outline drawing, shading, colouring) and modelling media and techniques for creative expression of design ideas', 'B7.1.2.1.3', 'Demonstrate ability to generate design ideas and develop models of simple shapes and forms for appreciation and display', 'Exemplar; 1. Identify simple products and generate drawings to illustrate templates for creating models of simple shapes and forms using cardboard, Styrofoam, pulp paper and/or clay for reflection, display and appreciation.; 2. Develop own drawings of templates and create models of simple shapes and forms using cardboard, Styrofoam, clay and/or pulp paper for appreciation and sharing.; 3. Display own drawings, templates and models of simple shapes and forms for appreciation, appraisal and feedback.', 60),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Creativity, Innovation and the Design Process', 'B7.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to identified problems in society', 'B7.1.3.1.1', 'Distinguish between creativity and innovation and their application for developing design solutions to problems in society', 'Exemplar; 1. Research and define the key differences between creativity and innovation for reflection and discussion.; 2. Apply knowledge of creativity and innovation to evaluate the design products that solve specific problems in society for appreciation. Example: Prosthetics in health, wheel chair for mobility, hearing aids.; 3. Examine specific artefacts available in the local community and report on specific challenges associated with their design for reflection and discussion.', 70),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Creativity, Innovation and the Design Process', 'B7.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to identified problems in society', 'B7.1.3.1.2', 'Demonstrate understanding of the design process in relation to creativity and innovations in design', 'Exemplar; 1. Research and record the concept, importance and application of the design process in creative problem solving for reflection and discussion. Examples: define, brief, research, ideation, invent, prototype, testing, refine.; 2. Analyse information gathered and describe the steps in the design process in relation to creativity and innovation for appreciation and sharing.; 3 Evaluate the design of different products and suggest ways in which they could be modified to solve other problems in society.', 80),
('Basic 7', 'Creative Arts', 'creative arts', 'Design', 'Creativity, Innovation and the Design Process', 'B7.1.3.1', 'Design Demonstrate understanding of creativity and innovation in terms of the design process, and its application in developing design solutions to identified problems in society', 'B7.1.3.1.3', 'Demonstrate ability to apply the design process to create artefacts that solve specific problems in the local community', 'Exemplar; 1. Apply knowledge of creativity and innovation to evaluate specific problems in society to deduce how the design process can be used to solve those problems for reporting and feedback.; 2. Reflect on feedback and apply relevant manual and digital tools, materials and techniques to design and create model artefacts that express own concept for solving specific problems in society for appreciation and display.; 3. Display design expressions and prototypes of artefacts to disseminate own creativity and innovation for appreciation and feedback.', 90),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.1', 'Visual Arts', 'B7.2.1.1.1', 'Identify and determine the nature and uses of tools, materials and techniques needed for still-life drawing and shading, pattern making and modelling', '5. Apply knowledge and skills in cleaning-up, maintaining and storing of tools, materials and equipment in a sustainable manner. Example: wash and clean brushes, pencils, etc., after use and apply oil on metallic tools to avoid rusting.', 100),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.1', 'Visual Arts', 'B7.2.1.1.2', 'Apply techniques of still-life drawing and shading to make own visual artworks', 'Exemplars 1. Identify and use the techniques in still-life drawing and shading to create own artworks. Examples: hatching, cross-hatching, smoothing, mass shading and stippling. 2. Use various shading techniques in still-life drawing to create own artworks. 3. Display artworks for appreciation and reflection and use appropriate language to give supportive and informative peer and self-evaluation. Example: “The work used the stippling technique to achieve a range of tones.’’', 110),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.1', 'Visual Arts', 'B7.2.1.1.3', 'Experiment by using the techniques to test and prepare clay, pulp paper (papier-mâché) for modelling', null, 120),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.1', 'Visual Arts', 'B7.2.1.1.4', 'Apply the techniques in pattern making using available media to create visual artworks', 'Exemplars 1. Identify and describe the techniques and media for pattern making. Examples: dabbing, direct and relief printing Media: paints 2. Apply relevant pattern making techniques with available media to create own visual artworks. Example of pattern making technique: sponging, veining, blowing, spraying, spattering, stippling, string pulling, wax-resist/crayon batik, marbling, scribbling, rubbing-in, rubbing-out, etc. 3. Display patterns for appreciation and reflection and use appropriate language to give supportive and informative peer and self-evaluation. Example: The use of dabbing was effective in creating a pattern.', 130),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.2', 'Performing Arts - Music: Demonstrate understanding and apply scale, note durational values and simple time beat patterns in music', 'B7.2.1.2.5', 'Sing in pitch the diatonic major scale when playing the John Curwen’s Hand Sign Game by Lahing or using solfege', 'Exemplars 1. Sing in pitch one octave ascending and descending from doh and/or any other scale degree. 2. Match the seven alphabets to the notes in the C major scale in the treble clef by placing them under their locations (i.e., on line or in space).', 140),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.2', 'Performing Arts - Music: Demonstrate understanding and apply scale, note durational values and simple time beat patterns in music', 'B7.2.1.2.6', 'Identify durational symbols and move/perform their value in relation to the semibreve', 'Exemplars 1. Internalise the arithmetic or numeral value of note durations against the crochet ( ) and perform by clapping. E.g. clapping the following lines individually or in groups', 150),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.2', 'Performing Arts - Music: Demonstrate understanding and apply scale, note durational values and simple time beat patterns in music', 'B7.2.1.2.7', 'Conduct songs in simple duple, triple and quadruple time', 'Exemplars 1. Explain the concept of time signature in simple time in music. 2. Rehearse and conduct a group by using simple time beat patterns and use peer- and self-evaluation to review work.', 160),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.3', 'Dance and Drama: Demonstrate understanding and apply media, voice and movement techniques in dance and drama', 'B7.2.1.3.8', 'Identify and demonstrate the various Ghanaian dance/body movements, positions and voice projection patterns', 'Exemplars 1. Identify and perform Ghanaian physical exercises, rhythmic/theatre games, simple dance movements, etc. 2. Examine, record and reflect on different types of voices in speech and song. 3. Use body posture and voice quality as instruments of performance in Ghanaian dance and drama. 4. Identify and demonstrate various facial expressions and gestures associated with Ghanaian dancing and acting and use peer- and self-evaluation.', 170),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Media and Techniques', 'B7.2.1.3', 'Dance and Drama: Demonstrate understanding and apply media, voice and movement techniques in dance and drama', 'B7.2.1.3.9', 'Explore and experiment with techniques of dance, body movements and voice projections in the Ghanaian performance space', null, 180),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.1', 'Visual Arts: Demonstrate the ability to use concept of the design process (idea development) to produce, display and appraise own creative artworks that reflect in the range of different times and cultures', 'B7.2.2.1.1', 'Design and produce own visual artworks that reflect the history and culture of the people of the local community', 'Exemplars 1. Gather and record relevant information for developing ideas to design own visual artworks that reflect the history and culture of the people of the local community. Example: making drawings and/or taking photographs of local buildings, people, schools, landscapes, sculpture pieces, graphic arts, textiles, basketry, jewellery, leatherworks, etc., 2. Apply recorded ideas and design thinking process to create 2D and 3D artworks to address social, cultural and historical problems in the community such as artworks of painting, landscape, poster design, repeat pattern or sculpture.', 190),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.1', 'Visual Arts: Demonstrate the ability to use concept of the design process (idea development) to produce, display and appraise own creative artworks that reflect in the range of different times and cultures', 'B7.2.2.1.2', 'Plan a display of own and others’ artworks that reflect the history and culture of the people in the community', 'Exemplars 1. Demonstrate understanding and skill in keeping portfolio of artworks. 2. Apply understanding and skills in planning, displaying and exhibiting artworks in class, school and the community to reflect the history and culture of the people in the community. 3. Reflect and use comments to refine own and others’ artworks and the exhibition.', 200),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.1', 'Visual Arts: Demonstrate the ability to use concept of the design process (idea development) to produce, display and appraise own creative artworks that reflect in the range of different times and cultures', 'B7.2.2.1.3', 'Organise an appreciation and appraisal of own and others artworks that reflect the history and culture of the people in the community', null, 210),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.2', '(CONTINUED) Performing Arts - Music: Demonstrate the ability to use concept of the design process (idea development) to create and display own creative musical art works that reflect the range of different times and cultures', 'B7.2.2.2.4', 'Exemplar 1 to a group of people (including learners, staff and parents) to collect data and write an aesthetic appreciation report', 'Exemplars 1. Research, select and record indigenous musical genre of the community that expresses personal experiences and interests, moods, visual images, concepts, texts, or storylines. 2. Create rehearsal plan for performing one of the selected works in Exemplar 1 by identifying and allocating time to the various aspects - singing, drumming, dancing, costume, venue, etc.', 220),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.2', '(CONTINUED) Performing Arts - Music: Demonstrate the ability to use concept of the design process (idea development) to create and display own creative musical art works that reflect the range of different times and cultures', 'B7.2.2.2.5', 'Plan a display of own and others’ musical works that reflect the history and culture of the people in the community', null, 230),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.2', '(CONTINUED) Performing Arts - Music: Demonstrate the ability to use concept of the design process (idea development) to create and display own creative musical art works that reflect the range of different times and cultures', 'B7.2.2.2.6', 'Organise an appreciation and appraisal of own and others’ musical works that reflect the history and culture of the people in the community', null, 240),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.3', 'Dance and Drama: Demonstrate the ability to use concepts of', 'B7.2.2.3.7', 'Design and produce own artworks in dance and drama that reflect the history and culture of the people in the community', null, 250),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.3', 'Dance and Drama: Demonstrate the ability to use concepts of', 'B7.2.2.3.8', 'Plan a display of own and others’ artwork in dance and drama that reflect the history and culture of the community', 'Exemplars 1. Describe how to plan a dance piece and drama skit for a performance. 2. Choose an appropriate venue to showcase the performance and spread the information about it. 3. Rehearse, perform and record the planned dance piece and drama skit.', 260),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Creative and Aesthetic Expression', 'B7.2.2.3', 'Dance and Drama: Demonstrate the ability to use concepts of', 'B7.2.2.3.9', 'Organise an appreciation and appraisal of own and others’ artworks in dance and drama that reflect the history and culture of the people of the community', 'Exemplars 1. Invite an audience to watch the performance of own and others for appreciation and appraisal. 2. Note and write the strengths and weaknesses of the production and performance for discussion and modification of future performances.', 270),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.1', 'Visual Arts: Demonstrate the ability to correlate and generate ideas from visual artworks in the community that reflect a range of different times, cultures and topical issues', 'B7.2.3.1.1', 'Narrate own views of the history, culture, environment and topical issues in the community', 'Exemplars 1. Identify and use a range of techniques such as observational drawings, sketches, own photographs and material such as adverts and images from the internet or from printed media, to record own views on the history, culture, environment and topical issues in the community. Examples: chieftaincy, landmarks, artists and artworks, events, festivals, tourist sites (natural and man-made). 2. Discuss and make individual or collaborative presentations on information recorded. Example: Using PowerPoint, Flip chart, Journal/Visual/Audio recordings such as drawings and photographs, verbal reports, assistive devices, etc. 3. Review and reflect on presentations to build consensus on the history, culture, environment and topical issues in the community.', 280),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.1', 'Visual Arts: Demonstrate the ability to correlate and generate ideas from visual artworks in the community that reflect a range of different times, cultures and topical issues', 'B7.2.3.1.2', 'Identify visual artworks that reflect the history, culture, environment and topical issues in the community', 'Exemplars 1. Scout for and record visual artworks found in the community by taking photographs and making drawings from direct observation where possible. Examples: Paintings, carvings, sculpture pieces, pottery works, posters, billboards, packages, textiles, baskets, weavings, jewellery, leather sandals, buildings. 2. Discuss, classify and group visual artworks found in the community according to their nature. Example: Painting (Homowo festival), Sculpture pieces (bust of the chief), Pottery (earthenware bowl), Graphic Arts (inscriptions on buildings), textiles (traditional cloths worn), basketry (cane /raffia chairs), jewellery (necklace, beads), leatherworks (scandals, shoes). 3. Discuss in groups to appraise how the history, culture, environment and topical issues in the community are reflected in the selected visual artworks and document your findings using art specific language such as content, colour scheme, symbolism, cultural significance.', 290),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.2', 'Performing Arts - Music: Demonstrate the ability to correlate and generate ideas from indigenous creative musical forms and art musicians in the immediate community that reflect a range of different times, cultures and topical issues', 'B7.2.3.2.3', 'Identify indigenous and art musicians in the community whose works reflect the history, culture, environment and topical issues', 'Exemplars 1. Select one indigenous or popular musician and assess their contribution to the society. Examples: Agya Koo Nimo, Afia Abaasa, Kakraba Lobi, Kojo Nuatro, E. T. Mensah, Kojo Antwi, Amakye Dede, Gyedu-Blay Ambolley 2. Transcribe any song in the community that promotes and sensitises the public on emerging topical issue. Examples: Sanitation song by Ubongo kids; Sanitation by Osei Boateng; Illegal Fishing by Kofi Kinaata; Driver Banza by George Jarrah.', 300),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.2', 'Performing Arts - Music: Demonstrate the ability to correlate and generate ideas from indigenous creative musical forms and art musicians in the immediate community that reflect a range of different times, cultures and topical issues', 'B7.2.3.2.4', 'Appreciate and appraise an indigenous and a neotraditional group within the community based on their style, instruments, song themes, dance movements, etc', null, 310),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.3', 'Dance and Drama: Demonstrate the ability to correlate and generate ideas from creative artworks of dancers and actors in the community that reflect a range of different times, cultures and topical issues', 'B7.2.3.3.5', 'Select artworks of dance and drama artistes in the community or other places, and identify the history, culture, environment and topical issues that are reflected in them', 'Exemplars 1. Research and write about the history, culture and important sites of the environment. 2. Select a dance or play and identify and write about the history, culture, environment and topical issues in them.', 320),
('Basic 7', 'Creative Arts', 'creative arts', 'Creative Arts', 'Connections in Local and Global Cultures', 'B7.2.3.3', 'Dance and Drama: Demonstrate the ability to correlate and generate ideas from creative artworks of dancers and actors in the community that reflect a range of different times, cultures and topical issues', 'B7.2.3.3.6', 'Analyse works of other dance and drama artistes based on the history, culture, environment and topical issues in and around their communities', 'Exemplars 1. Watch video clips of other artistes that reflect the historical, cultural and topical issues in dance and drama. 2. Analyse the video clips watched and document the historical, cultural and topical issues that are reflected in them. 3. Reflect on and discuss to generate ideas from the video clips watched.', 330),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Conversation/everyday Discourse', 'B7.1.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.1.1.1.1', 'Use appropriate register in everyday communication (informal and formal) with diverse partners on grade-level topics/texts/issues', 'Identify formal situations. E.g. interactions between strangers on varied themes, announcements, standards for work, school and public offices and business settings.; Use appropriate language to participate in formal interactions. (No slang/jargon).; Identify informal conversations: E.g. casual or intimate relationship between friends and acquaintances, family and teammates, different situations in the classroom etc.; Use appropriate language to participate in conversations in the following situations: Greetings, requests, encouragements, partings etc. NB: Examples of informal language include; slang words, jargon, contracted forms and non-verbal communication.', 10),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Conversation/everyday Discourse', 'B7.1.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.1.1.1.2', 'Ask questions that elicit elaboration and respond to others’ questions in conversation', 'Identify words that can help give elaborate responses to questions in conversation (e.g. why, how, for what reason).; Engage in conversation using these words to elicit elaboration E.g. Ama: Do you think girls should study courses in the male dominated areas? Aziz: Yes Ama: Why do you think so? NB: Includes gender, equity, equality, and inclusion issues.', 20),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Conversation/everyday Discourse', 'B7.1.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.1.1.1.3', 'Use appropriate language orally to describe experiences about oneself and others', 'Use o language: tense structures, variety of sentences, figurative expressions etc. o vocabulary: nouns, adjectives, adverbs, etc. to communicate about one’s experiences and those of others in specific situations e.g. the hospital, shopping in a market/supermarket, at a bus terminal/station, etc.', 30),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Conversation/everyday Discourse', 'B7.1.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.1.1.1.4', 'Listen to and give accurate directions to familiar places', 'Use appropriate language (e.g. opposite, adjacent, a few metres away, ten minute-walk /drive, turn left/right) and landmarks (church, mosque, hospital, filling station, etc.) to give directions.; Direct different individuals using a range of these vocabularies and expressions appropriately to given locations.', 40),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Conversation/everyday Discourse', 'B7.1.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.1.1.1.5', 'Use techniques (voice modulation and eye contact) for effective oral communication', 'Converse using appropriate voice (pace, volume, tone, stress) e.g. word and sentence stress. E.g.: increase (noun) and increase (verb).; Maintain eye contact (look in the eyes/face of the person speaking, maintain appropriate posture and facial expression) in conversation.; Engage in conversation using voice modulation and maintaining eye contact. Monitor how your partner shows this in the conversation. Demonstrate appropriate non-interruptive verbal and non-verbal cues/responses to show attention.', 50),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Listening Comprehension', 'B7.1.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B7.1.2.1.1', 'Listen to level-appropriate text attentively and identify key information', 'Identify key points: o intent or purpose of the message (e.g. to inform, persuade, instruct); o the speaker’s enthusiasm and passion for the topic; o main idea (s) and supporting points.; Read out and cross check the information written.', 60),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'Listening Comprehension', 'B7.1.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B7.1.2.1.2', 'Listen to, discuss ideas and share opinions from a level-appropriate text', 'Listen to and write key points from texts/speeches/presentations.; Discuss key points identified and share opinions.', 70),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'English Sounds', 'B7.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B7.1.3.1.1', 'Produce pure vowel sounds (short vowels) in context', 'Identify and produce pure vowels e.g. /a/, /i/, /e/ in context.; Articulate pure vowels clearly in speech.', 80),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'English Sounds', 'B7.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B7.1.3.1.2', 'Produce pure vowel sounds (long vowels) in context', 'Identify and produce long vowels in context. E.g.: part, peel, bloom.; Distinguish between long and short vowels in context.; Listen to and produce sounds as used in connected speech.', 90),
('Basic 7', 'English Language', 'english', 'Oral Language (listening and Speaking)', 'English Sounds', 'B7.1.3.1', 'Articulate English speech sounds to develop confidence and skills in listening and speaking', 'B7.1.3.1.3', 'Produce diphthongs in context (centring and closing)', 'Identify centring diphthongs e.g. /eǝ / /iǝ/ in context.; Identify closing diphthongs e.g. /au/, /ai/ in context.; Listen and distinguish between vowels and diphthongs in context.; Use vowels and diphthongs accurately in connected speech.', 100),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B7.2.1.1.1', 'Read and understand a range of texts using monitoring and mental visualisation strategies to interpret texts', 'Engage narrative texts and create mental pictures to aid understanding.; Read fluently to build confidence.; Engage in meaningful interaction with text and peers.; Monitor for understanding and self-correct where necessary.; Make connections with what is read to own experiences.', 110),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B7.2.1.1.2', 'Use prediction to assess and improve understanding of texts', 'Make predictions about the content of a text using: o prior knowledge; o typographical and visual features; o text features; o organisational patterns; o organisational structure.; Ask questions to form ideas.; Answer questions to elicit understanding (meaning).', 120),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B7.2.1.1.3', 'Generate and answer questions to increase understanding and independent reading of fiction texts', 'Read a text closely for implicit meaning.; Write questions to guide reading.; Look back at questions as you read and create a link with text.; Provide and interpret evidence to support understanding.; Answer questions accurately.; Use the answers to identify the main idea of the text.', 130),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.1', 'Demonstrate increasing confidence and enjoyment in independent reading', 'B7.2.1.1.4', 'Use text structure to understand and read texts independently', 'Interact with a variety of texts.; Examine the topic sentences that give clues to a specific structure.; Identify how the structure (how the information is organised) of the text influences meaning. These may include: o description, o sequence, o problem and solution, o cause and effect and o compare and contrast.; Use a graphic organiser to make a chart of the text structure.; Write paragraphs that follow a specific text structure.; Read independently and identify how text structure helps with understanding other texts.', 140),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.2', 'Read, comprehend and interpret texts', 'B7.2.1.2.1', 'Identify the main text features of a non-literary texts', 'Use samples of varied texts such as non-fiction – articles, formal letters (business letters, newsletters), etc. to identify text features (Print, Graphic, and Organisational): o Print Features: title, heading/sub-heading, bold Print, italics, caption, etc. o Graphic Features: Photograph with or without caption, Drawing, Diagram, Map, Graph, Chart, etc. o Organisational Features: Table of Content, Index, Glossary, etc.; Discuss how the text features aid in the comprehension of a text. E.g. o A title indicates the topic, subject matter or the main idea of an entire text. o Bold print signals important vocabulary and/or a phrase that is integral to understanding the content of a text.', 150),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.2', 'Read, comprehend and interpret texts', 'B7.2.1.2.2', 'Interpret non-fiction texts pointing out attitudes, opinions, biases and facts', 'Write out essential questions.; Read the text.; Make connections between texts and personal experiences.; Research or make inferences and share opinions on biases and facts in texts.; Distinguish between facts and opinions in a range of non-fiction texts. Interpret the different attitudes exhibited by the choice of words in texts to support understanding.', 160),
('Basic 7', 'English Language', 'english', 'Reading', 'Comprehension', 'B7.2.1.2', 'Read, comprehend and interpret texts', 'B7.2.1.2.3', 'Interpret a non-literary text showing personal responses and supporting responses with textual evidences', 'Read a variety of texts discussing the main ideas.; Identify how a writer’s choice of words and intentions contribute to meaning.; Differentiate viewpoints with textual evidence.; Examine the impact of different viewpoints and how these contribute to meaning.', 170),
('Basic 7', 'English Language', 'english', 'Reading', 'Summarising', 'B7.2.2.1', 'Demonstrate an understanding in summarising', 'B7.2.2.1.1', 'Use summarising to understand key ideas in a range of texts', 'Read a variety of passages and identify the main ideas.; Analyse and decide what is important. o Do not write the same words as the author. o Think and write in your own words. o Ask, “What is the whole write up about?”; Restate or map out the gist/main idea and key details.; Put up a defence for the choice/ answer.; Restate the main ideas in own words.', 180),
('Basic 7', 'English Language', 'english', 'Reading', 'Summarising', 'B7.2.2.2', 'Demonstrate understanding of textual evidence that supports a writing piece', 'B7.2.2.2.1', 'Determine and analyse central and supporting ideas of texts', 'Read a variety of texts for main ideas.; Identify the main idea/topic sentence in the paragraphs.; Identify supporting details and how these relate to main details in texts.; Summarise main ideas of texts in own words and peer edit it.', 190),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.1', 'Demonstrate command and application of nouns in speaking and texts', 'Identify noun types (common, proper, countable and uncountable, concrete) from passages.; Construct sentences using noun types.; Categorise plural noun forms (emphasis on irregular nouns) in passages e.g. mouse – mice, child – children, sheep – sheep, half – halves.; Use plural noun forms in paragraphs.', 200),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.2', 'Use types of pronouns accurately in speaking and texts', 'Explore the use of types of pronouns in narratives: o Personal Pronouns o Possessive Pronouns o Relative Pronouns o Reflexive Pronouns o Interrogative Pronouns o Demonstrative Pronouns; Use pronouns in contextual sentences.', 210),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.3', 'Explore accurate use of adjectives in texts', 'Recognise the effective use of adjectives in paragraphs: o directly before nouns. E.g. Asiedu is an excellent singer. o with the verb “to be” to describe the subject of the sentence. E.g. Adzo was very tired.; Use adjectives with sense verbs (sight, taste, smell, touch, hearing) or verbs of appearance to modify the nouns, which come before the verb. E.g. The fish tasted awful. He seemed very upset.', 220),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.4', 'Relate forms of verbs to everyday activities (Tense & Aspects) in context, role play, radio, TV, films and narratives Present Tense', '1. Identify the use of verbs that show present tense and aspect in sentences o simple present tense – I wash a car. o present progressive – I am washing a car. o present perfect – I have washed the car. o present perfect progressive – I have been washing the car Past Tense; 2. Identify the use of verbs that show past tense and aspect in sentences: o simple past tense – I washed the car. o past progressive – I was washing the car. o past perfect – I had washed the car. o past perfect progressive – I had been washing the car.', 230),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.5', 'Use adverbs to modify verbs accurately at the phrase and sentence level', '3. Recognise the effective use of adverbs in paragraphs; o to give more information about the verb. E.g. She slowly entered the room. o to give more information about the adjective. E.g. The test was extremely difficult.; 4. Explore using the first adverb to give more information about the second adverb in sentences. E.g. The cheetah runs incredibly quickly.', 240),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.6', 'Use conjunctions accurately to link ideas in everyday discourse', 'Explore sentences using coordinating conjunctions. E.g. for, and, nor, but, or, yet, and so.; Construct sentences using correlative conjunctions. E.g. either... or, neither... nor, and not only... but also.; Use subordinating conjunctions to link ideas. E.g. because, since, as, although, though, while, and whereas.; Use adverbs that function as conjunctions in sentences. E.g. until, after, or before.', 250),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.7', 'Demonstrate command of the use of prepositions in daily discourse (TV, radio, social media, news, home, role play)', 'Use complex prepositions (more than one word) in constructing sentences. e.g. consist of, in front of, on behalf of, in view of, in spite of, due to, near to, because of, by means of, by dint of (hard work), etc. E.g.: o The tree is in front of the house. o The prefect spoke on behalf of the class.; Use complex prepositions to express: o place e.g. near/close to, in front of, out of, far from, by the side of, etc. o time e.g. in time of, about to, during the course of, at noon, for one week, etc. o reason e.g. due to, because of, on account of, as a result of, etc. o concession e.g. in spite of, apart from etc.', 260),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.1', 'Apply the knowledge of word classes and their functions in Communication', 'B7.3.1.1.8', 'Identify and use determiners in speaking and texts', 'Identify determiners from texts. o Articles are the most popular types of determiners. E.g. definite article ‘the,’ indefinite ‘a,’ and ‘an.’ o Possessives provide context in a sentence by informing the reader what belongs to the subject, such as ‘our,’ ‘your,’ my,’ ‘their,’ ‘her,’ and ‘his’. E.g. Her car is over there. o Demonstratives (that, this, there, these, and those) identify an object based on its location.; Use determiners in sentences and paragraphs. E.g. That cat is very fat. An apple fell from the tree. Is your coffee on the counter?', 270),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.2', 'Demonstrate command of structural and functional use of sentences', 'B7.3.1.2.1', 'Identify and use subject and predicate in text', 'Distinguish elements of a sentence.; Use the knowledge of the composition of subject.; Know the composition of predicate of a sentence.', 280),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.3', 'Demonstrate command of structural and functional use of sentences', 'B7.3.1.3.1', 'Demonstrate command and use of compound sentences', 'Construct independent clauses. E.g. Kofi arrived late. He missed the exam.; Join two or more independent clauses to form compound sentences using coordinating conjunctions (and, but, or, so, etc.); Analyse compound sentences to identify the various independent clauses in them.', 290),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.4', 'Apply knowledge of clauses in communication', 'B7.3.1.4.1', 'Use dependent and independent clauses appropriately in speaking and writing', 'Recognise sentences as independent/dependent clauses in texts. E.g. We danced at the party all night long.; Construct sentences by combining dependent and independent clauses.', 300),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.5', 'Demonstrate understanding of the use of conditional tenses in communication', 'B7.3.1.5.1', 'Use conditional sentences in communication to indicate a possible condition and its possible result', 'Construct simple sentences using the future time, e.g. We will go home tomorrow.; Construct complex sentences and analyse them to show the main clause and the subordinate clause(s). e.g. When we came, they were at a meeting. When we came – subordinate clause They were at a meeting – main clause; Use if- clauses appropriately in communication (to indicate varied possible conditions and their possible results). e.g. If it rains, we will get there late.; Analyse given conditional sentences (main clause and subordinate clauses). Note: In a Type 1 conditional sentence, the tense in the ‘if ’ clause is the simple present, and the tense in the main clause is the simple future. E.g. I will be happy if you come to my party. The ‘If clause’ is the condition while main clause is the result and the order of the clauses are not fixed. Conditional sentence Type 1 is used to communicate real situations.', 310),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.6', 'Demonstrate mastery of use of active and passive voice', 'B7.3.1.6.1', 'Use passive sentences for a range of functions', 'Use the passive voice to: o describe processes. o talk/write about past actions (when we do not know who did them). o talk/write about past actions (when we know who did them). o write reports and other formal texts.; Construct sentences in the active voice (subject, verb and object). E.g. The class won the game.; Reconstruct active sentences into the passive voice. E.g. The game was won by the class.', 320),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.6', 'Demonstrate mastery of use of active and passive voice', 'B7.3.1.6.2', 'Demonstrate use and command of reported speech', 'Compose sentences in the direct speech and change them to reported speech.; Report what people say in formal and informal situations. e.g. ‘She agreed she would meet me after school.’ ‘He regretted he was busy on Saturday and wouldn’t be able to come.’ ‘You admitted there wasn’t any homework.’ ‘He reported he had been walking along the road when the car hit the tree.’; Compose news reports.', 330),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Grammar', 'B7.3.1.7', 'Show understanding and use of question tags in communication', 'B7.3.1.7.1', 'Use question tags accurately', 'Listen to dialogues involving question tags.; Identify statements with question tags. e.g. ‘You’re not going to play football today, are you?’ ‘You like tea, don’t you?’ ‘She’s older than me, isn’t she?’; Compose statements with question tags.', 340),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Punctuation and Capitalisation', 'B7.3.2.1', 'Demonstrate use and mastery of capitalisation and punctuation in communication', 'B7.3.2.1.1', 'Identify and use punctuation marks (question, exclamation, full-stop, comma) in given texts', 'Identify and use punctuation marks (question, exclamation, full- stop, comma) in given texts.; Correct punctuation errors in paragraphs.', 350),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Vocabulary', 'B7.3.3.1', 'Demonstrate appropriate use of vocabulary in communication', 'B7.3.3.1.1', 'Apply vocabulary appropriately in specific contexts', 'Use appropriate vocabulary in specific contexts and situations. E.g.:; 1. When asking for and giving advice Asking for advice: o I need some advice. I’ve no idea what to do. o What do you think I should do? o What would you recommend? o What would you do if you were me? o Do you think I should ...? Giving advice: possible suggestions o You could always … (go to the shop and ask for an exchange). o My advice would be to ... (take it back and ask for a refund). o What you need to do is ... (make a copy in case the original gets lost). o One thing you could do is ... (read your speech/presentation to a friend).; 2. When agreeing and disagreeing Agreeing: o I tend to agree with you. o That’s a good idea. o I’m with you on that point. o I’ll go along with that.; Disagreeing: o I see things differently. o I tend to disagree with that idea. o I agree up to a point. However, ... o You have a point there, but ... 3. when ordering food in a restaurant 4. when speaking at a friend’s birthday party 5. when in conversation with peers, adults etc.', 360),
('Basic 7', 'English Language', 'english', 'Grammar Usage', 'Vocabulary', 'B7.3.4.1', 'Demonstrate understanding of use of aesthetic language to enrich communication', 'B7.3.4.1.1', 'Explore the use of proverbs to enrich communication', 'Identify and examine proverbs in context to figure out their meanings.; Find Ghanaian proverbs to match the English ones identified.; Use proverbs to construct meaningful sentences.', 370),
('Basic 7', 'English Language', 'english', 'Writing', 'Production and', 'B7.4.1.1', 'Develop, organise and express ideas coherently and cohesively in writing', 'B7.4.1.1.1', 'Use cohesive devices (pronouns, punctuations and conjunctions) to link sentences', 'Consolidate basic understanding of compound sentences using conjunctions (connectives): nor, or, so, then, yet.; Write complex sentences using subordinating conjunctions: o time clauses: when, before, after, since, while, as, until o conditional clauses: if, unless o purpose clauses: in order to, so that o reason clauses: because, since, as o result clauses: so that o concessive clauses: although, though, while o place clauses: where, wherever o clauses of manner: as, like, the way.; Use pronouns to connect ideas in paragraphs: E.g. - subject pronouns (he, she, they, etc.) - object pronouns (me, him, them, etc.) - demonstrative pronouns (these, this, those, that); Use appropriate punctuation (question, exclamation, full-stop, comma, quotation (speech) marks). NB. Use logical connectors, pronouns and the repetition of words, synonyms and antonyms to create a cohesive text (i.e. a text in which sentences and paragraphs are linked together to show meaning and beauty).', 380),
('Basic 7', 'English Language', 'english', 'Writing', 'Production and', 'B7.4.1.2', 'Create different paragraphs on a given topic', 'B7.4.1.2.1', 'Organise information in a logical manner', 'Write a paragraph beginning with topic (main) sentence and supporting sentences.; Organise sentences in a logical sequence to create a coherent paragraph that is appropriate for the text type (narrative, descriptive, instruction (directions), persuasive, explanation (notice), etc.).; Use logical connectors to link sentences in a paragraph: o ordering ideas: firstly, secondly, finally, etc. o addition: moreover, furthermore, in addition, etc. o similarity: similarly, likewise, in the same way, etc. o contrast: however, nevertheless, although, though, on the other hand, etc. o cause/effect: because, therefore, as a result, consequently, etc. o sequence in time: next, soon, after, then, later, suddenly, afterwards, etc. NB. Use logical connectors, pronouns and the repetition of words, synonyms and antonyms to create a cohesive text (i.e. a text in which sentences and paragraphs are linked together to show meaning and beauty).', 390),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.1', 'Develop, organise and express ideas coherently and cohesively in writing for a variety of purposes (description, narration, exposition/information and persuasion), audiences and contexts', 'B7.4.2.1.1', 'Write personal narratives using effective techniques incorporating descriptive details and logical event sequences', 'Plan and record ideas detailing personal experiences or past events: o Use: - descriptive details (setting, experiences or series of events). - first-person point of view to convey feelings, experiences and thoughts. - appropriate grammatical structures.; adjectives and adjective phrases for producing vivid descriptions; adverbs and adverbials for describing how an action has been carried out; connectors for showing sequence of events; direct and indirect speech for variation and adding interest  nouns and noun phrases (e.g., participants, objects)  prepositions and prepositional phrases  first-person pronouns; Edit/Proofread the writing for sense, meaning and effect (targeted audience reaction).; Publish writing using different media including ICT.', 400),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.1', 'Develop, organise and express ideas coherently and cohesively in writing for a variety of purposes (description, narration, exposition/information and persuasion), audiences and contexts', 'B7.4.2.1.2', 'Use precise (technical) vocabulary, phrases and sensory language to convey a vivid mental picture of people and experiences', 'Describe people using precise words (e.g. He staggers, to say precisely how someone walks), phrases and sensory details (words that appeal to sight, sound, smell, taste, and touch).; Use appropriate grammatical structures: o adjectives and adjective phrases for producing vivid descriptions in paragraph o adverbs and adverbials for describing how an action has been carried out o connectors to show sequence of events and extend ideas o direct and indirect speech for variation and adding interest o nouns and noun phrases (e.g. participants, objects) o prepositions and prepositional phrase o first-person pronouns; Revise and edit the writing for sense or meaning, and effect (emotional reaction).; Proofread to self-correct or peer-correct.', 410),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.1', 'Develop, organise and express ideas coherently and cohesively in writing for a variety of purposes (description, narration, exposition/information and persuasion), audiences and contexts', 'B7.4.2.1.3', 'Create advertisements to persuade a given audience to take decisions on products and services', 'Compose advertisement for the sale of products, services, events following appropriate format/style using process approach: e.g. o Title o body – information about the product or service including design and pictures, the buyer (target market/audience) and selling points (what is good about the product or service, why is the product or service better than others?); Use: o the simple present for conveying timeless statements and facts o modals or imperative(command) for persuasive effect and hedging o mental verbs (e.g. I think, I believe) for conveying a viewpoint o verb phrases o rhetorical questions and repetition for persuasion; Edit/Proofread the writing for sense or meaning, and effect (emotional reaction).; Publish writing using different media including ICT', 420),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.1', 'Develop, organise and express ideas coherently and cohesively in writing for a variety of purposes (description, narration, exposition/information and persuasion), audiences and contexts', 'B7.4.2.1.4', 'Compose a paragraph to explain a process, social and natural phenomena (how to do or use something, how something works)', 'Write the steps taken to do or make something or how something works (e.g. rules of a game or sport, recipes, instructions on how to use a device, volcanic eruption, flooding) by: o writing the aim of the text o listing the materials needed o sequencing and/or describing items to be carried out or conditions to be observed o using appropriate text features (e.g., main headings, sub-headings, diagrams/illustrations, bullets/numbering); Use: o adjectives and adjective phrases for describing materials and objects o connectors for showing sequence in steps o nouns and noun phrases (e.g., ingredients in recipes) o quantifiers for indicating amounts of ingredients and materials o simple present for indicating the timeless nature of procedures', 430),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.1', 'Compose informal letters on varied topics using appropriate format', 'Identify features of informal letters (writer’s address, date, salutation, body, subscription, name).; Use the correct features of informal letters appropriately.; Write informal letters on a range of themes to friends and relatives. (E.g. of themes; school life, excursions, games, festivals etc.).; Correct errors of informal letters written by others.', 440),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.2', 'Compose formal writing (application, invitation, email, media texts) on given topics using appropriate format', 'Identify features of formal letters (writer’s address, recipient address, date, heading, salutation, body, subscription, signature, name, etc.).; Write formal letters to offices. (E.g. to the Headmaster/mistress, the Director of Education, the Assembly Man/woman, the SMC chairman/ chairperson, the PTA Chairman etc.).; Correct errors of formal letters written by others.; write notices to class or club members to provide updates on rules, schedules or programmes.; Create a variety of media texts for different purposes and audiences using appropriate forms, conventions, and techniques.; Reflect on and identify strengths, areas for improvement, and the strategies found most helpful in understanding and creating media texts.; Edit/Proofread the writing for sense or meaning, and effect (emotional reaction).; Publish writing using different media including ICT.', 450),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.3', 'Take notes for academic and other purposes', 'Identify and record: o source information (title, author, date etc.) o headings to help you identify the key topics o key points, examples, names, new ideas o triggers to make your notes more memorable – such as mnemonics, colour or drawings. o further reading and ideas to follow up later.; Identify and select key ideas.; Organise ideas and make connections.; Plan and structure written assignments.; Write notes while listening to the teacher, reading a text, viewing a video recording or revising.; Edit/Proofread the writing for sense or meaning, and effect (emotional reaction).; Record/represent writing in a flow chart, illustrations and notes in other media including ICT.', 460),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.4', 'Design notices and posters for different purposes and audiences', 'Write notices/posters of different lengths for different purposes and audiences, using appropriate forms, conventions, and techniques (posters on a school excursion, notices on voluntary cleaning etc.); Edit/Proofread the writing for sense or meaning, and effect (emotional reaction).; Record/represent writing in a flow chart and illustrations and other design packages including ICT.', 470),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.5', 'Write articles on given issues for publication in class and club magazines', 'Identify the topic for, purpose of, and audience for article writing.; Generate ideas about more challenging topics and identify those most appropriate for the purpose.; Write, using a variety of strategies and a wide range of print and electronic resources.; Sort and classify ideas and information for writing a variety of articles.; Write articles of different lengths on given issues for publication(e.g., a rap poem or jingle, to express a personal view to the class; a report for a community newspaper about a public meeting on an environmental issue affecting local neighbourhoods; an autobiography for a youth magazine, issues on gender and inclusion, web page, blog, or zine).', 480),
('Basic 7', 'English Language', 'english', 'Writing', 'Text Types and Purposes', 'B7.4.2.2', 'Apply writing skills to specific life situations', 'B7.4.2.2.6', 'Create dialogues between two interlocutors on different themes', 'Compose dialogues of different lengths on given topics by using the following strategies: o say the dialogue out loud o keep your dialogue brief and impactful o give each character a unique voice o add world-appropriate slang o be consistent with the characters’ voices o remember who they are speaking to o avoid long dialogue paragraphs o cut out greetings; Use appropriate grammatical conventions and structures e.g. o capitalisation o use of speech (quotation) marks o comma o question mark where needed o full-stops', 490),
('Basic 7', 'English Language', 'english', 'Writing', 'Building and Presenting Knowledge', 'B7.4.3.1', 'Research to build and present knowledge', 'B7.4.3.1.1', 'Identify and record information from non-text sources (figures and tables), organise and present it in writing', 'Identify and record: o source information (title, author, date etc.) o headings to help you identify the key topics o key points, examples, names, new ideas o triggers to make your notes more memorable – such as mnemonics, colour or drawings. o further reading and ideas to follow up later.; Identify and select key ideas.; Organise ideas and make connections: (Write sentences to describe simple graphical data accurately).; Edit/Proofread the writing for sense or meaning, and effect.; Record/represent writing in a flow chart, illustrations and notes in other media including ICT.; Describe simple graphical data in words during presentation.', 500),
('Basic 7', 'English Language', 'english', 'Literature', 'Narrative, Drama and Poetry', 'B7.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B7.5.1.1.1', 'Demonstrate understanding of oral literature (narratives, poetry, drama) and how the different genres contribute to meaning', 'Narrative o Identify and distinguish between the types of oral narratives: folktales, myths and legends. o Write simple folktales, myths and legends.; Poetry o Read aloud and distinguish between the types of poetry by function (African poems such as dirges, lullabies, war and praise songs) paying attention to the rhythmic variations. o Discuss the cultural and social significance of the poems. o Write and recite poems (African poems such as dirges, lullabies, war and praise songs).; Drama o Read and listen to traditional drama (drama according to social function: outdooring, puberty rites, marriages, festivals and enstoolment/enskinment etc.) texts. o Distinguish types of traditional drama according to their social functions. o Determine cultural/social significance of drama. o Act or perform a traditional drama.', 510),
('Basic 7', 'English Language', 'english', 'Literature', 'Narrative, Drama and Poetry', 'B7.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B7.5.1.1.2', 'Analyse the elements of written literature (narrative, drama, or poetry)', 'Narrative o Identify and describe the plot, setting, characters. o Compare plot, setting and characters between two texts. o Compose and read out simple narratives.; Drama o Identify and describe the plot, setting, characters. o Compare plot, setting and characters between two texts. o Compose and act out a simple drama.; Poetry o Read and distinguish between poems looking at the different types and functions. o Discuss and make connections with values in poems o Compose and perform poems illustrating values e.g. love for neighbour, respect for one another and public property etc.', 520),
('Basic 7', 'English Language', 'english', 'Literature', 'Narrative, Drama and Poetry', 'B7.5.1.1', 'Demonstrate understanding of how various elements of literary genres contribute to meaning', 'B7.5.1.1.3', 'Use basic literary devices in texts (', 'e.g. metaphor, simile, personification, alliteration, assonance, consonance, etc.); Identify the use of basic literary devices in selected genres (poetry, narrative and drama).; Use basic literary devices in texts (e.g. metaphor, simile, personification, alliteration, assonance, consonance, etc).', 530),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage - Childhood Rites', 'B7.1.1.1', 'Demonstrate knowledge and understanding of the childhood rites of their culture and compare with other Ghanaian cultures', 'B7.1.1.1.1', 'Identify the processes involved in naming a child', '1. Discuss the outdooring and the naming process of a child in their community.; E.g. outdooring/ushering the baby, invitation of ancestors, giving the baby a name, blessing, presentation of gifts (father, person child was named after, family, community), and so on. NB: Let learners watch a video on the traditional naming process and discuss it.; 2. Identify the items used in the naming process and write them. E.g.: water, basket, bucket, beads, basin, mat, powder, lantern, clothes (baby and mother).; 3. Explain the significance of the items used for the naming ceremony. NB: In some communities the outdooring and the naming process are two different things.', 10),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage - Childhood Rites', 'B7.1.1.1', 'Demonstrate knowledge and understanding of the childhood rites of their culture and compare with other Ghanaian cultures', 'B7.1.1.1.2', 'Discuss the significance of the processes in naming a child', '1. Read a words on naming ceremony in their culture.; 2. Discuss the significance of the processes involved in naming a child as raised in the passage. E.g.; Welcomes the child into the family and community.; The child gets an identity.; 3. Discuss a libation text used during naming ceremony.; 4. Write the three main parts of a libation text.', 20),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage - Childhood Rites', 'B7.1.1.1', 'Demonstrate knowledge and understanding of the childhood rites of their culture and compare with other Ghanaian cultures', 'B7.1.1.1.3', 'Compare and contrast the naming processes in their culture to other Ghanaian cultures', '1. Discuss the naming process of one other culture of Ghana and compare with the naming process of their people.; 2. Write about commonalities and differences among the cultures.', 30),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage - Childhood Rites', 'B7.1.1.1', 'Demonstrate knowledge and understanding of the childhood rites of their culture and compare with other Ghanaian cultures', 'B7.1.1.1.4', 'Compare and contrast the traditional naming process to the contemporary naming process', '1. Discuss the contemporary naming processes and compare it with the traditional naming processes in Ghana.; 2. Show the similarities and differences. Similarities: e.g.; It is organised; Family members are involved.; Presentation of gifts, etc. Differences: e.g.; Organised in the family house but now organised at other places, e.g. church, in front of houses, event places, etc.; Items used are different from the contemporary process.; Baby named eight days after birth (but these days it is not always the case), etc.', 40),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Rites of Passage - Childhood Rites', 'B7.1.1.1', 'Demonstrate knowledge and understanding of the childhood rites of their culture and compare with other Ghanaian cultures', 'B7.1.1.1.5', 'Role play a naming ceremony session in their culture', '1. Role play a naming ceremony among their people.; 2. Discuss the role play and what they have learnt from it. NB: The facilitator should make sure that ALL learners get equal chance to participate in the role play not forgetting gender roles.', 50),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems: Day Names, Order of Birth Names', 'B7.1.2.1', 'Exhibit understanding of day- born names and order of birth names and relate the names to the days and order of birth', 'B7.1.2.1.1', 'State the names of the days of the week and relate their names to the days', '1. State the names of the days of the week and important occasion (e.g. festival) months of the year in the Ghanaian language of study.; 2. Relate the names of the days of the week or months of the year to human names. Monday Female Male Akan:; Adwoa; Kodwo/Kwadwo Dangme/Ga:; Ajo; Kojo Ewe:; Adzo; Kɔdzo/Kudzo Gonja:; Atani; N/A NB: The day naming system is not applicable to all cultures of Ghana. It is language specific. The teacher should watch out for cultural shocks and address it skilfully.; Female; • Adwoa; • Ajo; • Adzo; • Atani', 60),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems: Day Names, Order of Birth Names', 'B7.1.2.1', 'Exhibit understanding of day- born names and order of birth names and relate the names to the days and order of birth', 'B7.1.2.1.2', 'State the order of birth (i.e. first, second, and so on.) and relate the names accordingly', '1. State the order of birth of their culture.; E.g. first born, second born, and so on.; 2. Relate the names to the order of birth.; E.g.: First born Female Male; Piesie (Akan) Piesie (Akan); Gogo (Ewe-Peki) Foli (Ewe-Peki); Dede (Dangme) Tɛte (Dangme); Ayele (Ga) Ayite (Ga) Second born NB: The order of birth names is not applicable to all cultures of Ghana. It is language specific. The teacher should watch out for cultural shocks and address it skilfully.', 70),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'Naming Systems: Day Names, Order of Birth Names', 'B7.1.2.1', 'Exhibit understanding of day- born names and order of birth names and relate the names to the days and order of birth', 'B7.1.2.1.3', 'Compare and contrast the day names and order of birth names in their culture to other cultures in Ghana', '1. Compare the day names and order of birth names in their culture with those of other cultures in Ghana.; 2. Discuss the similarities and differences. Similarities:; E.g.: Both are done in order, etc. Differences:; E.g.: Same names for both sexes in some cultures but not same in other cultures, etc.; Female; Piesie (Akan); Gogo (Ewe-Peki); Dede (Dangme); Ayele (Ga)', 80),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.3.1', 'Demonstrate an understanding of the clan system among their people', 'B7.1.3.1.1', 'Describe the clan system and state some clans in their ethnic community', '1. Explain what a clan is.; 2. State some clans you know. NB: Learners associate themselves with the clans stated. E.g.:; Akan: Aduana, Agona, etc.; Dangme: Dangmebiawɛ, Piɛngua, Kabubiawɛ, Jebiam, etc.; Ewe (Aŋlɔ): Bateawo, Adzɔviawo, etc.; Ga: Sempe (Ga Mashi), Kinkawe (Osu), Abese (La), Agbawe (Tɛshi), Nii Moi We(Nuŋua), Jɔɔshi(Tɛma) etc.; Gonja: Nsuwa, Ngbanyabia, etc.; Dagaare: Emoala/Ewaala, Kusiele, etc.', 90),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.3.1', 'Demonstrate an understanding of the clan system among their people', 'B7.1.3.1.2', 'Discuss the features of the clan system in relation to their community', '1. Discuss the features of their clan system. E.g. symbols, taboos, totems, names, etc.; 2. Relate their clan system to another clan system.; 3. Read a passage on a clan system.; 4. Write the main ideas in the passage read in their own words.', 100),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.4.1', 'Demonstrate knowledge in and an understanding of how chiefs and queenmothers are selected, enstooled/ enskinned and compare their duties and responsibilities', 'B7.1.4.1.1', 'Discuss how chiefs and queenmothers are selected in their ethnic community', '1. Read a passage on how chiefs and queenmothers are selected in their community.; 2. Identify the traditional leaders mentioned in the passage. E.g. chiefs, sub- chiefs, and so on.; 3. Relate how chiefs and queenmothers are selected among their people to the passage read.', 110),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.4.1', 'Demonstrate knowledge in and an understanding of how chiefs and queenmothers are selected, enstooled/ enskinned and compare their duties and responsibilities', 'B7.1.4.1.2', 'Discuss the processes involved in enstooling/enskinning chiefs and queenmothers', '1. Discuss the qualities of a person who qualifies to be a chief or a queenmother among your people.; 2. Create a profile of the qualities of a chief or queenmother.; 3. Identify those who select the chief and queenmother among your people.; 4. Role play the enstoolment/enskinment of chiefs and queenmothers. Learners watch a video on the topic before the role play. NB: Some cultures of Ghana do not have queenmothers but have female chiefs. The facilitator should make sure that ALL learners take active part in the role play.', 120),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.4.1', 'Demonstrate knowledge in and an understanding of how chiefs and queenmothers are selected, enstooled/ enskinned and compare their duties and responsibilities', 'B7.1.4.1.3', 'Discuss the duties and responsibilities of chiefs and queenmothers among their people', '1. Identify the duties of a chief and queenmother in their community.; 2. Evaluate the duties of a chief and queenmother among your people.', 130),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Customs and Institutions', 'The Clan System', 'B7.1.4.1', 'Demonstrate knowledge in and an understanding of how chiefs and queenmothers are selected, enstooled/ enskinned and compare their duties and responsibilities', 'B7.1.4.1.4', 'Discuss and compare modern trends affecting the enstoolment/enskinement of chiefs and queenmothers', '1. Discuss some modern trends affecting the enstoolment/enskinement of chiefs/queenmothers among your people. E.g. Monetary influence, political influence, etc.; 2. Explain how the trends mentioned affect the chieftaincy institution.; 3. Compare the modern ways of enstooling/enskinning chiefs/ queenmothers with the traditional ways of enstooling/enskinning chiefs/ queenmothers.', 140),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B7.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.2.1.1.1', 'Use appropriate register in everyday communication (informal and formal) with diverse partners on grade-level topics/ texts/issues', '1. Identify formal situations. E.g. interactions between strangers on varied themes, announcements, standard for work, school and public gathering and offices, at the palace and business settings, and hospitals.; 2. Use appropriate language to participate in formal interactions. e.g. no slang/jargon, no contracted forms. Learner should go online and read on the topic.; 3. Identify informal situations: E.g. casual or intimate relationship between friends and acquaintances, family and team mates, etc.; 4. Use appropriate language to participate in conversations in the following situations: Greetings, requests, encouragements, partings, etc. (Examples of informal language include slang words, jargons, contracted forms, non-verbal communication)', 150),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B7.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.2.1.1.2', 'Ask questions that elicit elaboration and respond to others’ questions in a conversation', '1. Identify words that can help give elaborate responses to questions in conversation (e.g. why, how, for what reason).; 2. Engage in conversation using these words to elicit elaboration. E.g. Ama: Do you think babies should talk? Dɛre: Yes Ama: Why do you think so?', 160),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B7.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.2.1.1.3', 'Use appropriate language orally to describe experiences about oneself and others', '1. Use appropriate language: tense structures, variety of sentences, figurative expressions, etc.; 2. Use appropriate vocabulary: nouns, adjectives, adverbs, etc. to talk about one’s experiences and those of others in specific situations e.g. at the hospital, shopping in a market/supermarket, at a bus terminal/station, etc.', 170),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B7.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.2.1.1.4', 'Listen to and give accurate directions to familiar places', '1. Use appropriate language (e.g. opposite, adjacent, a few metres away, ten minute-walk /drive, turn left/right) and landmarks (church, mosque, hospital, filling station etc.) to show direction.; 2. Direct people using a range of these vocabulary and expressions appropriately to given locations.', 180),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Conversation/everyday Discourse', 'B7.2.1.1', 'Demonstrate use of appropriate language orally in specific situations', 'B7.2.1.1.5', 'Use techniques (voice modulation and eye contact) for effective oral communication', '1. Converse using appropriate voice (pace, volume, tone); 2. Maintain eye contact (look at the person speaking, maintain appropriate posture and facial expression in conversation.; 3. Engage in conversation using the right tone and maintaining eye contact. Monitor how your partner shows this in the conversation.', 190),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B7.2.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B7.2.2.1.1', 'Listen to a level-appropriate text attentively and identify key information', '1. Identify key points:; Intent or purpose of the message (e.g. to inform, persuade, instruct).; Assess the speaker’s enthusiasm and passion for the topic.; Identify main ideas and supporting points in the text.; 2. Read out and cross check the information written.', 200),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B7.2.2.1', 'Demonstrate the ability to listen to extended reading and identify key information', 'B7.2.2.1.2', 'Listen to, discuss ideas and share opinions from a level- appropriate text', '1. Listen to and write key points from texts/speeches/presentations.; 2. Discuss key points identified and share opinions with peers.', 210),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B7.2.3.1', 'Recognise and sound vowels and consonants and read one syllable words of their linguistic community', 'B7.2.3.1.1', 'Identify and produce the vowels in the language of study', '1 Identify vowels in words. 2 Produce the vowel sounds of your language. e.g. /a/, /e/, /ɛ/. etc. 3 Record the vowel sounds of your language. 4 Pronounce vowel sounds correctly in connected speech.', 220),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B7.2.3.1', 'Recognise and sound vowels and consonants and read one syllable words of their linguistic community', 'B7.2.3.1.2', 'Identify and produce the consonants in the language of study', '1. Identify consonants in words.; 2. Produce the consonant sounds of your language. E.g. /b/, /f/, /g/. etc.; 3. Record the consonant sounds of your language.; 4. Pronounce consonant sounds correctly and fluently in connected speech.', 230),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Listening Comprehension', 'B7.2.3.1', 'Recognise and sound vowels and consonants and read one syllable words of their linguistic community', 'B7.2.3.1.3', 'Identify and produce one to four syllable words of the language of study', '1. Read one syllable words.; E.g.: Akan: Kɔ, ba, tu, etc. Dagaare: Kɔ, ba, tu, etc. Dangme: Kɔ, ba, tu, etc. Ewe: Kɔ, ba, tu, etc. Ga: Kɔ, ba, tu, etc. Gonja: Kɔ, ba, tu, etc.', 240),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Tone', 'B7.2.4.1', 'Recognise the basic tones in their language', 'B7.2.4.1.1', 'Identify and produce the basic tones in their language', '1. Identify the tones on syllables in their language. E.g.: low ( ˋ ), high ( ʹ ), and mid ( ˉ ).; 2. Pronounce words with tones correctly and fluently in connected speech.; 3. Use the knowledge of tone to pronounce same words that have different tones in context.', 250),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Vocabulary Development (sight and Content Vocabulary)', 'B7.2.5.1', 'Exhibit an understanding of recognising and producing words and using them in sentences', 'B7.2.5.1.1', 'Identify and produce words in the home and school environments and use them to form meaningful sentences', '1. Identify vocabulary items in relation to the home.; E.g. dining, cooking, bathing, etc. (the vocabulary items should be mentioned in the language of study); 2. Identify vocabulary items in relation to the school.; E.g. classroom, headteacher’s office, school compound, etc. (the vocabulary items should be mentioned in the language of study); 3. Use the vocabularies identified to form meaningful sentences.', 260),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Listening and Speaking', 'Presentation — Everyday Experience', 'B7.2.6.1', 'Present information effectively on familiar topics using appropriate language', 'B7.2.6.1.1', 'Describe daily activities using appropriate register, structure and gestures for the contest being presented', '1. Outline some activities that you do on a daily basis.; 2. Narrate with gestures what you do in the morning before school, at school and after school.; 3. Develop a daily activity calendar.; 4. Converse with others about daily activities.; 5. Make a presentation on other familiar topics, e.g. family, school, holidays, weather, hobbies, animals, hometown or village, favourite time of the year and festival.', 270),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Reading', 'B7.3.1.1', 'Understand the main ideas and supporting points in texts', 'B7.3.1.1.1', 'Read and understand main ideas and supporting points in a range of texts on familiar and unfamiliar topics', '1. Skim a given passage of about one hundred and fifty words and state the main ideas.; 2. Identify the supporting ideas in texts on themes from other subject areas. (E.g. Social Studies, Science, Religious and Moral Education, Physical Education, ICT, etc.); 3. Explain the relationship between the main ideas and supporting ideas.; 4. Answer recall and inferential questions concerning the text read. NB: As learners read, watch out for those with speech impairment and assist them to avoid being mocked at.', 280),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Reading', 'B7.3.1.1', 'Understand the main ideas and supporting points in texts', 'B7.3.1.1.2', 'Read to understand and summarise the main ideas in a given grade level passage', '1. Identify and write main ideas in passages read from a range of subject areas.; 2. List the ideas identified in the order in which they occur in a passage.; 3. Summarise a passage of about one hundred and fifty words in fifty words using your own words.', 290),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Reading', 'Translation', 'B7.3.2.1', 'Demonstrate knowledge of translating words. Phrases and simple sentences', 'B7.3.2.1.1', 'Translate words and phrases in his/her language', '1. Translate given words and simple phrases from the source language to a target language.; 2. Translate phrases simple sentences from the source language of study to a target language.; 3. Translate simple sentences from the source language to a target language.', 300),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Sentences — Simple, Compound and Complex', 'B7.4.1.1', 'Demonstrate knowledge and understanding of the components of sentences', 'B7.4.1.1.1', 'Discuss the components of sentences', '1. Explain what a sentence is.; 2. Give examples of sentences and their component parts in their language.; 3. Discuss the components of a sentence in their language.', 310),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Sentences — Simple, Compound and Complex', 'B7.4.1.1', 'Demonstrate knowledge and understanding of the components of sentences', 'B7.4.1.1.2', 'Discuss the types of sentence structure (simple, compound and complex)', '1. Identify the components of a simple sentence in their language and give examples.; 2. Identify the components of a compound sentence in their language and give examples.; 3. Identify the components of a complex sentence in your language and give examples.', 320),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Sentences — Simple, Compound and Complex', 'B7.4.1.1', 'Demonstrate knowledge and understanding of the components of sentences', 'B7.4.1.1.3', 'Classify sentences according to functions (declarative, imperative and interrogative)', '1. Identify the functions of a sentence.; 2. Construct some sentences in relation to their functions.; E.g. To ask a question, etc.', 330),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (nouns, Pronouns and Adjectives)', 'B7.4.2.1', 'Demonstrate knowledge of identifying and using the various forms of nouns (common, proper, collective), pronouns and adjectives in sentences and passages', 'B7.4.2.1.1', 'Categorise nouns under common, proper and collective and use them correctly in speech and in texts', '1. Identify nouns in a passages.; 2. Classify the nouns identified into common, proper and collective nouns.; 3. Pronounce the nouns and use them correctly in speech and texts.; 4. Construct simple and compound sentences (orally and in written forms) with the types of nouns identified.', 340),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (nouns, Pronouns and Adjectives)', 'B7.4.2.1', 'Demonstrate knowledge of identifying and using the various forms of nouns (common, proper, collective), pronouns and adjectives in sentences and passages', 'B7.4.2.1.2', 'Categorise pronouns according to their types and construct sentences with them', '1. Identify pronouns in a passage.; 2. Classify the pronouns into their types.; 3. Construct sentences with the types of pronouns in speaking and writing individually and in mixed ability groups.; 4. Replace nouns with the appropriate pronoun in a passage.', 350),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (nouns, Pronouns and Adjectives)', 'B7.4.2.1', 'Demonstrate knowledge of identifying and using the various forms of nouns (common, proper, collective), pronouns and adjectives in sentences and passages', 'B7.4.2.1.3', 'Categorise adjectives into their types and construct simple sentences with them', '1. Identify adjectives from passages.; 2. Classify the adjectives into their types.; 3. Use the adjectives to form simple and compound sentences in speaking and writing.', 360),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs, Conjunctions, Postpositions/prepositions)', 'B7.4.3.1', 'Recognise the use of verbs, adverbs, conjunctions and postpositions/ Prepositions in sentences', 'B7.4.3.1.1', 'Identify and classify verbs into their types', '1. Identify and use verbs appropriately and correctly in passages and in speaking and writing.; 2. Categorise the verbs into types and use them to construct simple and compound sentences.', 370),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs, Conjunctions, Postpositions/prepositions)', 'B7.4.3.1', 'Recognise the use of verbs, adverbs, conjunctions and postpositions/ Prepositions in sentences', 'B7.4.3.1.2', 'Identify and classify adverbs into their various types', '1. Identify and use adverbs appropriately and correctly in simple sentences in speaking and writing.; 2. Categorise the verb into types and use them to construct simple and compound sentences in speaking and writing individually and in mixed ability groups.', 380),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs, Conjunctions, Postpositions/prepositions)', 'B7.4.3.1', 'Recognise the use of verbs, adverbs, conjunctions and postpositions/ Prepositions in sentences', 'B7.4.3.1.3', 'Identify and classify conjunctions and use them appropriately in a range of texts', '1. Identify and use conjunctions appropriately and correctly in simple and compound sentences in speaking and writing.; 2. Categorise the conjunctions into types and use them to construct simple and compound sentences.', 390),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Integrating Grammar in Written Language (verbs, Adverbs, Conjunctions, Postpositions/prepositions)', 'B7.4.3.1', 'Recognise the use of verbs, adverbs, conjunctions and postpositions/ Prepositions in sentences', 'B7.4.3.1.4', 'Explore the use of postpositions/prepositions appropriately and correctly in a range of texts', '1. Identify and use postpositions/prepositions appropriately in simple and compound sentences in speaking and writing.', 400),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Vocabulary, Spelling and Punctuation', 'B7.4.4.1', 'Demonstrate knowledge and understanding of vocabulary, spelling and punctuations in writing', 'B7.4.4.1.1', 'Use vocabulary appropriately and correctly in writing', '1. Identify and write vocabulary related to home and school.; 2. Use the vocabulary of identified items to construct appropriate and correct sentences.', 410),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Vocabulary, Spelling and Punctuation', 'B7.4.4.1', 'Demonstrate knowledge and understanding of vocabulary, spelling and punctuations in writing', 'B7.4.4.1.2', 'Spell words related to home and school correctly', '3. Write down vocabulary items related to home and school dictated correctly.; 4. Construct sentences with the vocabulary items written down.', 420),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Language and Usage', 'Vocabulary, Spelling and Punctuation', 'B7.4.4.1', 'Demonstrate knowledge and understanding of vocabulary, spelling and punctuations in writing', 'B7.4.4.1.3', 'Identify and use punctuations appropriately and correctly in writing', '1. Use punctuation marks appropriately in about a fifty-word paragraph.', 430),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Structure and Organise Ideas in Composition Writing', 'B7.5.1.1', 'Demonstrate knowledge and understanding of the features of a paragraph and the various text types (narrative, descriptive, creative/free writing)', 'B7.5.1.1.1', 'Discuss the features of a paragraph', '1. Ability to write the topic and supporting sentences of a paragraph.; 2. Develop the skills of expressing and organising ideas in paragraphs.; 3. Identify the salient points/ideas in a given paragraph.; 4. Write a paragraph of about fifty words on a given topic taking into consideration the features and skills of paragraph writing.', 440),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Composition Writing', 'Structure and Organise Ideas in Composition Writing', 'B7.5.1.1', 'Demonstrate knowledge and understanding of the features of a paragraph and the various text types (narrative, descriptive, creative/free writing)', 'B7.5.1.1.2', 'Develop a three-paragraph essay using the features of a given text type', '1. Discuss the features of narrative, descriptive, creative/free writing.; 2. Write a three-paragraph essay on a topic on the text types above.', 450),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Literature', 'Folktales, Songs, Prose, Drama, Poetry', 'B7.6.1.1', 'Demonstrate the knowledge and understanding of literature (Oral and Written)', 'B7.6.1.1.1', 'Discuss the components of literature', '1. Discuss the characteristics of literature.; 2. Classify literature into types.; 3. Give examples and relate to the types; 4. Develop the skills of appreciating and analysing literary texts.', 460),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Literature', 'Folktales, Songs, Prose, Drama, Poetry', 'B7.6.1.1', 'Demonstrate the knowledge and understanding of literature (Oral and Written)', 'B7.6.1.1.2', 'Discuss the components of oral literature (folktales and songs-lullabies and play songs)', '1. Explain what oral literature is.; 2. Describe the structure of a folktale and a song.; 3. Analyse a folktale and a song.; 4. Appreciate the significance of a folktale and a song.', 470),
('Basic 7', 'Ghanaian Language', 'ghanaian language', 'Literature', 'Folktales, Songs, Prose, Drama, Poetry', 'B7.6.1.1', 'Demonstrate the knowledge and understanding of literature (Oral and Written)', 'B7.6.1.1.3', 'Discuss the components of written literature (prose, drama and poetry)', '1. Discuss the structure of the various genres of written literature.; 2. Discuss how characters are created in a range of prose, poetry and drama texts.; 3. Explore ways that writers use literary devices, mood and tone in a range of prose, poetry and drama texts.', 480);
