-- NaCCA curriculum for Basic 7 (part 1 of 2): 177 indicators (Career Technology, Creative Arts, English Language, Ghanaian Language).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 7.
delete from public.curriculum_items
 where lower(class_name) = 'basic 7' and subject_key in ('career technology', 'creative arts', 'english', 'ghanaian language');

